namespace LocalSpt5Esp;
internal static class AiEquipmentEditor {
 sealed record Field(string Key,string Name,PropertyInfo Property);
 sealed class Original {internal Item Item=null!;internal ItemTemplate Template=null!,Copy=null!;internal IArmorComponentTemplate? Armor;internal IKnifeComponentTemplate? Knife;internal IRepairableComponentTemplate? Repair;internal ItemComponentParameters Parameters=null!;internal LiveActorReference Actor=null!;}
 static readonly Dictionary<IntPtr,Original> originals=new();static readonly List<Item> parts=new();static readonly List<Field> fields=new();static readonly Dictionary<string,string> drafts=new();static readonly HashSet<string> enabled=new();
 static readonly EquipmentSlot?[] slots={EquipmentSlot.Headwear,EquipmentSlot.ArmorVest,EquipmentSlot.Eyewear,EquipmentSlot.FaceCover,null,EquipmentSlot.Scabbard,EquipmentSlot.TacticalVest,EquipmentSlot.Pockets};static readonly string[] names={"头甲","护甲","眼镜","面罩","武器","近战","弹挂","口袋"};static readonly EquipmentSlot[] weapons={EquipmentSlot.FirstPrimaryWeapon,EquipmentSlot.SecondPrimaryWeapon,EquipmentSlot.Holster};static readonly string[] weaponNames={"第一主武器","第二主武器","手枪"};
 static readonly Dictionary<string,string> labels=new(){["Weight"]="重量（千克）",["armorClass"]="防护等级",["BluntThroughput"]="钝伤穿透",["speedPenaltyPercent"]="移动速度修正",["mousePenalty"]="转向速度修正",["weaponErgonomicPenalty"]="武器工效修正",["BlindnessProtection"]="闪光防护",["knifeHitSlashDam"]="挥砍伤害",["knifeHitStabDam"]="刺击伤害",["SlashPenetration"]="挥砍穿透",["StabPenetration"]="刺击穿透",["PrimaryDistance"]="挥砍距离",["SecondryDistance"]="刺击距离",["knifeHitRadius"]="命中范围",["knifeHitDelay"]="命中延迟",["knifeHitSlashRate"]="挥砍速度",["knifeHitStabRate"]="刺击速度",["PrimaryConsumption"]="挥砍体力消耗",["SecondryConsumption"]="刺击体力消耗",["StaminaBurnRate"]="体力损伤"};
 static LiveActorReference? actor;static Item? selected;static string selectedId="",notice="";static int slot,page,part;static ItemComponentEditor? componentEditor;static Vector2 scroll,partScroll,frameScroll;static float nextCheck;static bool cloneReady;
 internal static bool Open=>actor!=null;
 internal static void Close(){WeaponEditor.CloseAi();actor=null;selected=null;componentEditor=null;parts.Clear();fields.Clear();}
 internal static void Select(GameWorld world,Player player){if(!cloneReady)CheckNativeClone();Close();actor=new(world,player);slot=page=part=0;scroll=partScroll=frameScroll=Vector2.zero;notice="";ReadSlot();}
 internal static void CheckNativeClone(){var factory=Singleton<ItemFactory>.Instance??throw new InvalidOperationException("装备编辑暂不可用。");const string fixture="657baaf0b7e9ca9a02045c02";var first=factory.CreateItem(factory.NextId.ToString(),fixture,null);var second=factory.CreateItem(factory.NextId.ToString(),fixture,null);var a=first.GetItemComponent<ArmorComponent>()??throw new InvalidOperationException("护甲检查未通过。");var b=second.GetItemComponent<ArmorComponent>()??throw new InvalidOperationException("护甲检查未通过。");if(a.Pointer==b.Pointer)throw new InvalidOperationException("护甲组件未隔离。");var source=first.Template.Cast<ArmoredEquipmentTemplate>();int original=source.armorClass;var copy=source.MemberwiseClone().Cast<ArmoredEquipmentTemplate>();copy.armorClass=original==1?2:1;first._Template_k__BackingField=copy;a.Template=copy.Cast<IArmorComponentTemplate>();if(a.ArmorClass!=copy.armorClass||b.ArmorClass!=original||source.armorClass!=original)throw new InvalidOperationException("护甲参数未隔离。");cloneReady=true;Plugin.Self.Log.LogInfo("AI equipment native clone check passed: independent components, per-item armor template rebind, unchanged sibling/source");}
 static Player Target()=>actor?.Resolve()??throw new ArgumentException("请重新选择 AI。");
 static Item? Root()=>slot>=0&&slot<slots.Length&&slots[slot] is EquipmentSlot equipment?Target().Profile?.Inventory?.Equipment?.GetSlot(equipment)?.ContainedItem:null;
 static ItemTemplate Concrete(Item item)=>item.Template.TryCast<KnifeTemplate>()??item.Template.TryCast<ArmoredEquipmentTemplate>()??item.Template.TryCast<EquipmentTemplate>()??item.Template;
 static void ReadSlot(){selected=null;componentEditor=null;parts.Clear();if(slot==4)return;var root=Root();if(root==null)return;var seen=new HashSet<IntPtr>();void Add(Item item,int depth){if(depth>8||!seen.Add(item.Pointer))return;parts.Add(item);if(item.TryCast<CompoundItem>()?.Slots is { } children)foreach(var child in children)if(child?.ContainedItem is Item nested)Add(nested,depth+1);}Add(root,0);part=Math.Clamp(part,0,Math.Max(0,parts.Count-1));Read(parts[part]);}
 static void Read(Item item){selected=item;selectedId=item.Id;componentEditor=new(item,new ItemComponentParameters());drafts.Clear();enabled.Clear();fields.Clear();var template=Concrete(item);foreach(var pair in labels){var property=template.GetType().GetProperty(pair.Key,BindingFlags.Public|BindingFlags.Instance);if(property?.CanRead!=true||property.CanWrite!=true||property.PropertyType!=typeof(float)&&property.PropertyType!=typeof(int))continue;fields.Add(new(pair.Key,pair.Value,property));drafts[pair.Key]=Convert.ToDouble(property.GetValue(template)).ToString("G9",CultureInfo.InvariantCulture);}scroll=Vector2.zero;}
 static Item Require(){var target=Target();if(selected==null||selected.Id!=selectedId)throw new ArgumentException("装备已改变，请重新选择。");var root=Root();if(root==null)throw new ArgumentException("该装备槽已清空。");bool present=root.Pointer==selected.Pointer;if(!present&&root.TryCast<ContainerCollection>() is ContainerCollection collection)present=collection.TryFindItem(selected.Id,out var found)&&found?.Pointer==selected.Pointer;if(!present)throw new ArgumentException("这件物品已离开该 AI 的装备槽。");return selected;}
 static Original Own(Item item){if(originals.TryGetValue(item.Pointer,out var original))return original;var template=Concrete(item);var copyObject=template.MemberwiseClone();var copy=(ItemTemplate)(Activator.CreateInstance(template.GetType(),copyObject.Pointer)??throw new InvalidOperationException("无法准备装备参数。"));if(copy.Pointer==template.Pointer)throw new InvalidOperationException("无法隔离该装备。");var armor=item.GetItemComponent<ArmorComponent>();var repair=item.GetItemComponent<RepairableComponent>();original=new(){Item=item,Template=template,Copy=copy,Armor=armor?.Template,Knife=item.GetItemComponent<KnifeComponent>()?.Template,Repair=repair?._template,Parameters=LoadoutPlans.Parameters(item),Actor=actor!};item._Template_k__BackingField=copy;if(armor!=null&&copy.TryCast<IArmorComponentTemplate>() is IArmorComponentTemplate armorTemplate)armor.Template=armorTemplate;if(repair!=null&&copy.TryCast<IRepairableComponentTemplate>() is IRepairableComponentTemplate repairTemplate)repair._template=repairTemplate;if(item.GetItemComponent<KnifeComponent>() is {} knife&&copy.TryCast<IKnifeComponentTemplate>() is {} knifeTemplate)knife.Template=knifeTemplate;originals[item.Pointer]=original;return original;}
 static void Refresh(Item item){item.RaiseRefreshEvent(true,true);var target=Target();target.RecalculateEquipmentParams();target.Physical?.MarkWeightAsDirty();}
 static void Apply(){var item=Require();var parameters=componentEditor?.Read()??new();var values=new Dictionary<Field,double>();foreach(var field in fields)if(enabled.Contains(field.Key))values[field]=WeaponEditorRules.Number(drafts[field.Key],field.Property.PropertyType==typeof(int),slot==5||field.Key is "Weight" or "armorClass"?0:double.NegativeInfinity);var original=Own(item);var previous=LoadoutPlans.Parameters(item);var templateValues=values.Keys.ToDictionary(field=>field,field=>field.Property.GetValue(original.Copy));try{foreach(var pair in values)pair.Key.Property.SetValue(original.Copy,pair.Key.Property.PropertyType==typeof(int)?(object)checked((int)pair.Value):(float)pair.Value);parameters.Apply(item);foreach(var pair in values){double actual=Convert.ToDouble(pair.Key.Property.GetValue(original.Copy));double requested=pair.Key.Property.PropertyType==typeof(int)?pair.Value:(float)pair.Value;if(actual!=requested)throw new InvalidOperationException("该参数未能生效："+pair.Key.Name);}var armor=item.GetItemComponent<ArmorComponent>();if(values.Any(pair=>pair.Key.Key=="armorClass"&&armor!=null&&armor.ArmorClass!=pair.Value))throw new InvalidOperationException("防护等级未能生效。");Refresh(item);var actualAttributes=LoadoutPlans.Parameters(item).Attributes();var differences=parameters.Attributes().Where(pair=>!actualAttributes.TryGetValue(pair.Key,out var current)||!Equals(current,pair.Value)).Select(pair=>ItemComponentParameters.AttributeName(pair.Key)+"："+actualAttributes.GetValueOrDefault(pair.Key)).ToArray();notice=differences.Length==0?"装备参数已更新":"已更新，部分参数已调整："+string.Join("；",differences);FeatureToasts.Show("AI 装备参数已更新");}catch{foreach(var pair in templateValues)pair.Key.Property.SetValue(original.Copy,pair.Value);previous.Apply(item);Refresh(item);throw;}}
 static void Restore(Original original,bool parameters){try{var item=original.Item;if(item?.Template?.Pointer==original.Copy.Pointer)item._Template_k__BackingField=original.Template;var armor=item?.GetItemComponent<ArmorComponent>();if(armor?.Template?.Pointer==original.Copy.Pointer&&original.Armor!=null)armor.Template=original.Armor;var repair=item?.GetItemComponent<RepairableComponent>();if(repair?._template?.Pointer==original.Copy.Pointer&&original.Repair!=null)repair._template=original.Repair;var knife=item?.GetItemComponent<KnifeComponent>();if(knife?.Template?.Pointer==original.Copy.Pointer&&original.Knife!=null)knife.Template=original.Knife;if(parameters&&item!=null)original.Parameters.Apply(item);item?.RaiseRefreshEvent(true,true);}finally{originals.Remove(original.Item.Pointer);}}
 static void RestoreSelected(){var item=Require();if(originals.TryGetValue(item.Pointer,out var original))Restore(original,true);Refresh(item);Read(item);notice="已恢复修改前的参数";}
 internal static void ForgetRemoved(Item root){var pointers=new HashSet<IntPtr>();void Visit(Item item){if(!pointers.Add(item.Pointer))return;foreach(var child in LootDisplay.Children(item))Visit(child);}Visit(root);foreach(var original in originals.Values.Where(value=>pointers.Contains(value.Item.Pointer)).ToArray())Restore(original,false);}
 internal static void RemovalFinished(LiveActorReference removedActor){if(actor?.World==removedActor.World&&actor.Pointer==removedActor.Pointer&&actor.Profile==removedActor.Profile){notice=AiEquipmentRemoval.Status;ReadSlot();}}
 internal static void Tick(GameWorld? world){if(world==null)AiEquipmentRemoval.Reset();else AiEquipmentRemoval.Tick();if(world!=null&&Time.unscaledTime<nextCheck)return;nextCheck=Time.unscaledTime+.5f;foreach(var original in originals.Values.ToArray())try{var owner=original.Actor.Resolve();var equipment=owner.Profile?.Inventory?.Equipment;bool present=equipment?.TryFindItem(original.Item.Id,out var found)==true&&found?.Pointer==original.Item.Pointer;if(!present)Restore(original,false);}catch{try{Restore(original,false);}catch{}}if(actor!=null){if(world==null||world.Pointer!=actor.World)Close();else try{actor.Resolve();}catch{Close();}}}
 internal static void Reset(){AiEquipmentRemoval.Reset();foreach(var original in originals.Values.ToArray())try{Restore(original,false);}catch{}Close();}
 static void Action(Action action){try{action();}catch(Exception e){notice=e.Message;Plugin.Self.Log.LogWarning("AI equipment: "+e.Message);}}
 internal static void Draw(Rect rect,bool embedded=false){if(WeaponEditor.AiOpen){WeaponEditor.DrawAi(rect);return;}AiEditorViewport.Draw(rect,ref frameScroll,"equipment",embedded,area=>DrawCore(area,embedded));}
 static void DrawCore(Rect rect,bool embedded){float x=rect.x,y=rect.y,w=rect.width;if(!embedded&&InterfaceMenu.Button(new Rect(x,y,126,32),"返回 AI 设置")){Close();return;}if(!embedded){InterfaceMenu.Label(new Rect(x+144,y,w-144,32),(actor?.Name??"AI")+" · 装备",InterfaceMenu.Accent,19);y+=50;}int columns=AiEditorLayout.EquipmentColumns(w);float cell=(w-8*(columns-1))/columns;for(int i=0;i<names.Length;i++)if(InterfaceMenu.Button(new Rect(x+i%columns*(cell+8),y+i/columns*44,cell,36),names[i],slot==i)){slot=i;part=0;scroll=Vector2.zero;notice="";Action(ReadSlot);}y+=((names.Length+columns-1)/columns)*44+10;
  if(slot==4){var view=new Rect(x,y,w,Math.Max(80,rect.yMax-y-78));scroll=GUI.BeginScrollView(view,scroll,new Rect(0,0,w-20,weapons.Length*128));float rowWidth=w-26;for(int i=0;i<weapons.Length;i++){int index=i;Item? item=null;Action(()=>item=Target().Profile?.Inventory?.Equipment?.GetSlot(weapons[index])?.ContainedItem);float top=i*128;InterfaceMenu.Surface(new Rect(0,top,rowWidth,116),Color.Lerp(InterfaceMenu.Background,InterfaceMenu.Text,.04f),9);InterfaceMenu.Label(new Rect(14,top+8,rowWidth-28,25),weaponNames[i],InterfaceMenu.Accent,15);InterfaceMenu.Label(new Rect(14,top+39,rowWidth-28,28),item==null?"未装备":LootDisplay.ItemName(item,false),null,13);float weaponHalf=(rowWidth-40)/2;bool old=GUI.enabled;GUI.enabled=old&&item?.TryCast<Weapon>()!=null&&!AiEquipmentRemoval.Busy;if(InterfaceMenu.Button(new Rect(14,top+76,weaponHalf,30),"修改武器参数"))Action(()=>WeaponEditor.OpenAi(Singleton<GameWorld>.Instance!,Target(),weapons[index]));if(InterfaceMenu.Button(new Rect(26+weaponHalf,top+76,weaponHalf,30),"删除武器（含配件）"))Action(()=>AiEquipmentRemoval.Start(actor!,weapons[index],item!));GUI.enabled=old;}GUI.EndScrollView();InterfaceMenu.Paragraph(new Rect(x,rect.yMax-62,w,58),AiEquipmentRemoval.Busy?AiEquipmentRemoval.Status:notice,InterfaceMenu.Accent,13);return;}
  if(selected==null){InterfaceMenu.Paragraph(new Rect(x,y+14,w,52),notice.Length>0?notice+"\n该槽位没有装备。":"该槽位没有装备。",null,15);if(InterfaceMenu.Button(new Rect(x,y+86,160,36),"重新读取"))Action(ReadSlot);return;}
  InterfaceMenu.Label(new Rect(x,y,w-140,30),LootDisplay.ItemName(selected,false),InterfaceMenu.Accent,16);if(InterfaceMenu.Button(new Rect(x+w-130,y,130,30),"刷新装备"))Action(ReadSlot);y+=44;
  if(slot is 6 or 7){if(InterfaceMenu.Button(new Rect(x,y,w,34),"编辑"+names[slot]+"内部物品"))Action(()=>AiBackpackEditor.Select(Singleton<GameWorld>.Instance!,Target(),slots[slot]!.Value));y+=48;}
  if(slot is 0 or 5){bool old=GUI.enabled;GUI.enabled=old&&!AiEquipmentRemoval.Busy;if(InterfaceMenu.Button(new Rect(x,y,w,34),AiEquipmentRemoval.Busy?"正在处理装备…":slot==5?"删除近战武器（含配件）":"删除整件头甲（含已装配件）"))Action(()=>{var root=Root()??throw new ArgumentException("该槽位没有头甲。");AiEquipmentRemoval.Start(actor!,slot==5?EquipmentSlot.Scabbard:EquipmentSlot.Headwear,root);});GUI.enabled=old;y+=48;if(selected==null)return;}
  if(parts.Count>1){var view=new Rect(x,y,w,64);partScroll=GUI.BeginScrollView(view,partScroll,new Rect(0,0,parts.Count*190,54));for(int i=0;i<parts.Count;i++)if(InterfaceMenu.Button(new Rect(i*190,2,180,44),i==0?"主体":LootDisplay.ItemName(parts[i],false),part==i)){part=i;Read(parts[i]);}GUI.EndScrollView();y+=78;}
  if(InterfaceMenu.Button(new Rect(x,y,(w-10)/2,34),"耐久与状态",page==0)){page=0;scroll=Vector2.zero;}if(InterfaceMenu.Button(new Rect(x+(w+10)/2,y,(w-10)/2,34),"防护与属性",page==1)){page=1;scroll=Vector2.zero;}y+=48;var area=new Rect(x,y,w,Math.Max(70,rect.yMax-y-124));float height=page==0?(componentEditor?.Height??50):Math.Max(80,fields.Count*58+36);scroll=GUI.BeginScrollView(area,scroll,new Rect(0,0,w-20,height));if(page==0)componentEditor?.Draw(w-32);else for(int i=0;i<fields.Count;i++){var field=fields[i];bool on=enabled.Contains(field.Key);if(InterfaceMenu.Button(new Rect(0,i*58,36,36),on?"✓":"",on)){if(!enabled.Remove(field.Key))enabled.Add(field.Key);}InterfaceMenu.Label(new Rect(50,i*58,w*.5f-50,36),field.Name,null,14);drafts[field.Key]=InterfaceMenu.Field(new Rect(w*.54f,i*58,w*.46f-32,36),drafts[field.Key]);}GUI.EndScrollView();float bottom=rect.yMax-110;float half=(w-12)/2;if(InterfaceMenu.Button(new Rect(x,bottom,half,38),"应用修改"))Action(Apply);if(InterfaceMenu.Button(new Rect(x+half+12,bottom,half,38),"恢复修改前参数"))Action(RestoreSelected);InterfaceMenu.Paragraph(new Rect(x,rect.yMax-62,w,58),notice,InterfaceMenu.Accent,13);
 }
